// 已知旧投影逐段升级；原始备份不改，自定义未知内容不覆盖。
var FR_PRESET_TWO_LAYER_LEGACY = {
  "item-no-free-init": "- 所有NPC与离场物品变化都必须由本次已确认散文明示；不得因缺数据、身份或时间跨度主动补物。",
  "item-no-empty-bag-init": "3. 仅在已确认散文明示该新NPC实际获得物品时创建，不因背包为空初始化物资。",
  "item-offscreen-gain": "4. 离场NPC只有在本次散文明示已完成购买、采集或炼制并实际入手后才获得物品。",
  "item-offscreen-use": "2. 离场NPC只扣减本次散文明示已经消耗的物品，不按时间跨度或动机另推消耗。",
  "item-no-auto-equip": "1. 本次散文明示已穿戴/装备已有物品时才装备，不主动初始化四件套。",
  "item-no-bonded-init": "- 重要NPC或羁绊人物也不得因 inventory 或装备为空自动补齐。仅落实本次已确认散文的明确物品事实。",
  "item-initialization-sections": "## 散文物品事实核对\n只把本次已确认散文的获得、转移、消耗、装备变化映射为原操作。空包、缺失数据、新人身份和离场时长都不构成发物或发灵石的依据。无明确变化返回空操作。\n\n",
  "item-cot-init": "Phase 2: 已确认散文物品事实\n逐条核对散文明示已成立的变化；没有相应事实不初始化、不补四件套、不补物资或灵石。\n\n",
  "item-existing-data-audit": "## 补演转换审计范围\n以下快照、数值、旧物回填与刷新审计，只允许校正已存在对象且有已保存依据或本次散文明示的事实。不得凭空补物，不重新掷随机参数，不以刷新改归属。\n\n## Step 0A:"
};
function frPresetTwoLayerUpgrade(text) {
  var value=String(text||'');
  FR_PRESET_PROSE_PATCHES.forEach(function(patch){var previous=FR_PRESET_TWO_LAYER_LEGACY[patch.key];if(previous && previous!==patch.newText && !value.includes(patch.newText))value=value.split(previous).join(patch.newText);});
  return value;
}
function frNpcFirstInventoryRules(text) {
  return String(text||'')
    .replaceAll(FR_PRESET_TWO_LAYER_LEGACY['item-no-free-init'],
      '- 已建档 NPC 及离场人物按实际剧情结算；仅明确标记「首次建档」的 NPC 可补合理的基础物品。')
    .replaceAll(FR_PRESET_TWO_LAYER_LEGACY['item-no-empty-bag-init'],
      '3. 仅首次建档的 NPC 可按身份和境界建立合理的装备与私物，空包不触发补发。')
    .replaceAll(FR_PRESET_TWO_LAYER_LEGACY['item-no-bonded-init'],
      '- 已建档 NPC 即使背包或装备栏为空也只结算已确认事实；首次建档以角色标记为准。')
    .replaceAll(FR_PRESET_TWO_LAYER_LEGACY['item-initialization-sections'],
      '## 首次建档与物品事实核对\n首次建档按身份、职业、境界合理补基础配置；已建档只结算实际变化。\n\n')
    .replaceAll(FR_PRESET_TWO_LAYER_LEGACY['item-cot-init'],
      'Phase 2: 首次建档与已确认物品事实\n有首次建档标记时合理设置起始私物和可用装备；已建档只登记实际变化。\n\n');
}
function frAdaptNpcFirstInventory(preset){
  if(!/^(?:ds-)?(?:full|light)$/.test(preset.frBuiltinCatalogId||''))return preset;
  for(const rule of frPresetCompatRules(preset,'item_management')){
    if(['im-operation-rules','im-cot'].includes(rule.id)&&typeof rule.content==='string')
      rule.content=frNpcFirstInventoryRules(rule.content);
  }
  return preset;
}
FR_PRESET_PROSE_FINAL_PATCHES.forEach(function(patch){
  if(patch.scope!=='item_management')return;
  var before=frPresetTwoLayerUpgrade(patch.oldText.slice(0,patch.start)),middle=frPresetTwoLayerUpgrade(patch.oldText.slice(patch.start,patch.end)),after=frPresetTwoLayerUpgrade(patch.oldText.slice(patch.end));
  patch.oldText=before+middle+after;patch.start=before.length;patch.end=before.length+middle.length;patch.newText=frPresetTwoLayerUpgrade(patch.newText);
});

function frPresetCompatCopy(value) {
  return JSON.parse(JSON.stringify(value));
}

function frPresetCompatMeta(preset) {
  var meta = preset.frPresetCompat;
  if (!meta || typeof meta !== 'object' || Array.isArray(meta)) meta = {};
  meta.schemaVersion = 1;
  if (!meta.backups || typeof meta.backups !== 'object') meta.backups = {};
  if (!Array.isArray(meta.backups.rules)) meta.backups.rules = [];
  if (!meta.backups.phases || typeof meta.backups.phases !== 'object') meta.backups.phases = {};
  if (!Array.isArray(meta.warnings)) meta.warnings = [];
  preset.frPresetCompat = meta;
  return meta;
}

function frPresetCompatWarning(meta, scope, rule, reason) {
  if(reason==='fortune_trait_custom_rule_preserved'&&typeof CE_CORE==='object'&&CE_CORE?.['numeric-preset']?.isCompressedNumericRule?.(scope,rule?.id,rule?.content))return;
  var id = String(rule && rule.id || '');
  var name = String(rule && rule.name || '');
  if (!meta.warnings.some(function(w) { return w.scope === scope && w.id === id && w.name === name && w.reason === reason; })) {
    meta.warnings.push({scope:scope,id:id,name:name,reason:reason});
  }
}

function frPresetCompatBackup(meta, scope, rule) {
  var key = rule.id ? 'id:' + rule.id : 'name:' + String(rule.name || '');
  if (!meta.backups.rules.some(function(b) { return b.scope === scope && b.key === key; })) {
    meta.backups.rules.push({scope:scope,key:key,rule:frPresetCompatCopy(rule)});
  }
}

function frPresetCompatRules(preset, scope) {
  var phase = preset.prompts && preset.prompts[scope];
  return phase && Array.isArray(phase.rules) ? phase.rules : [];
}

function frPresetPruneRetired(preset) {
  var meta=frPresetCompatMeta(preset);
  if(meta.retiredCleanupVersion===1)return preset;
  if(!Array.isArray(meta.backups.retiredRules))meta.backups.retiredRules=[];
  Object.keys(preset.prompts||{}).forEach(function(scope){
    var phase=preset.prompts[scope];if(!phase||!Array.isArray(phase.rules))return;
    phase.rules=phase.rules.filter(function(rule,index){
      if(!rule||rule.enabled!==false||!String(rule.name||'').includes('已停用'))return true;
      if(!meta.backups.retiredRules.some(function(row){return row.scope===scope&&row.index===index&&row.rule.id===rule.id;}))meta.backups.retiredRules.push({scope:scope,index:index,rule:frPresetCompatCopy(rule)});
      return false;
    });
  });
  meta.retiredCleanupVersion=1;
  return preset;
}

