    var hasContractLike = rules.some(function (r) {
      return r && typeof r.content === 'string' && r.content.indexOf(FR_ITEM_DOMAIN_CONTRACT_TITLE) >= 0;
    });
    if (hasContractLike) frPresetCompatWarning(meta, 'sharedRules', { id: 'c-rule-shared' }, 'shared_domain_boundary_not_extracted');
