    if (!Array.isArray(patch.path) || typeof patch.id !== 'string' || typeof patch.oldText !== 'string' || typeof patch.newText !== 'string') return;
    if (patch.path.some(function(key) { return ['__proto__','constructor','prototype'].includes(key); })) return;
    var list = preset;
    patch.path.forEach(function(key) { list = list && typeof list === 'object' && Object.prototype.hasOwnProperty.call(list,key) ? list[key] : null; });
    if (!Array.isArray(list)) return;
