function frRetirePublishedInactiveGroups(preset) {
  var meta=frPresetCompatMeta(preset);
  Object.keys(FR_RELEASED_INACTIVE_GROUPS).forEach(function(scope){
    var group=preset.prompts&&preset.prompts[scope];if(!group)return;
    var signature=frCompatSha256Hex(JSON.stringify(group));
    if(FR_RELEASED_INACTIVE_GROUPS[scope].indexOf(signature)<0){frPresetCompatWarning(meta,scope,{id:scope},'inactive_custom_group_preserved');return;}
    if(!meta.backups.retiredGroups)meta.backups.retiredGroups={};
    meta.backups.retiredGroups[scope]=frPresetCompatCopy(group);
    delete preset.prompts[scope];
  });
}

function frRetireBuiltinLegacyEquipmentSections(preset) {
  if (!/^(?:ds-)?(?:full|light)$/.test(preset.frBuiltinCatalogId || '') ||
      typeof window==='undefined' || !window.FrEquipmentRuntime) return;
  ['sharedRules','itemSharedRules'].forEach(function(scope){
    (Array.isArray(preset[scope])?preset[scope]:[]).forEach(function(rule){
      var text=String(rule.content || '');
      if (rule.id==='c-slots' && text.includes('## 四类槽位，每类 6 格')){
        rule.content='装备栏位、分类与结丹期本命法宝门槛统一遵守本请求中的「装备命名槽位」合同。';
      } else if (['c-rule-shared','c-rule-item','item-shared-item-columns'].includes(rule.id)) {
        rule.content=text.split(/(?=^## )/m).filter(function(section){
          return !/^## 装备槽位\s*\n/.test(section)||!/没有饰品槽|每类\s*6\s*格/.test(section);
        }).join('').trimEnd();
      }
    });
  });
}

function frCurrentItemExamplesRule() {
  return {
    id:'standalone-current-item-examples', name:'按类写完整物品与实际装备', enabled:true,
    content:[
      '先按物品实际功能分类，再填写对应原生列。下列示例是落地后的字段形状，仅供参考，数量、材料、品阶和功法效果均须据本轮资料填写，不照抄样品或用样品作得物证据。第0列由当前阶段按自身 ID 契约处理；不输出物品第9至11列。',
      '第2列分类使用：武器、护甲（头部／身体／腿部／饰品由 equipmentRole 区分）、法宝（含本命、飞行等用途）、功法（主修／炼体／神识／百艺由 equipmentRole 区分）、丹药、符箓、食物、油料、消耗品、材料、药材、阵盘、重要物品、杂物或其他物品。器类与品阶用第4列容器描述，不与物品分类混写。',
      '分类顺序：可持续修习的成体系法门或百艺教材→功法；手持用于攻防→武器，穿戴防护→对应护甲位，独立御使→法宝；用掉或耗尽→消耗品；用于配制或炼制的原料→材料；仅在有持有依据且用途为纪念、凭证或任务时才归重要物品；普通工具或杂物按自身用途。书、玉简、卷轴只是载体，不决定分类。此处按用途的具体判例优先于旧通用物品示例。',
      '【武器】{"1":"青钢剑","2":"武器","3":"青钢锻成的单手剑","4":"可斩击与格挡","5":"1","equipmentRole":"weapon"}',
      '【护甲】{"1":"护身皮甲","2":"护甲","3":"加厚熟革缝制的上身护甲","4":"抵御轻微划伤","5":"1","equipmentRole":"body"}。头部、腿部、饰品用相同列，分别标明 head、legs、accessory；不把普通衣着直接当护甲。',
      '【法器／法宝】{"1":"青光飞梭","2":"法宝","3":"御空赶路的梭形法宝","4":"容器: 法宝·上品 | 加成: 脚力 | 传导率: 0.30 | 门槛: 400/900","5":"1"}。武器法器写 weapon，防护法器写对应护甲位，普通法宝及其他可用宝物进普通法宝位。本命法宝用 natal，需有本命事实且本人已到结丹期。',
      '【主修功法】{"1":"引气口诀","2":"功法","3":"墨居仁所授长春功入门经卷","5":"1","6":"入门口诀","7":"只载入门","8":"入门：调息并感应气息","equipmentRole":"main"}。第6、7、8列须给实际品阶、可修上限和各境界修习效果；无依据不要把入门经卷当完整长春功，也不要编造额外境界或加成。主修、炼体、神识、百艺分别用 main/0、body/1、spirit/2、craft/3。单次施展的法术或学会的技艺是技能，并非持续修习的功法；若另有实体教程，按实体用途另行归类。',
      '【百艺功法】{"1":"辨药基础","2":"功法","3":"墨居仁所授的辨药入门经卷","5":"1","6":"基础教材","7":"辨药入门","8":"入门：识别常见药草，学习按药性和用途归类","equipmentRole":"craft"}。用这本经卷持续学习辨药时装备到百艺；已习得的采药等技能可同时记录，不替代经卷。',
      '【丹药／消耗品】{"1":"止血散","2":"丹药","3":"研细并用纸包封存的药散","4":"外敷止血，一包一次","5":"2"}。符箓、食物、油料等分别写实际用法和计量单位。',
      '【材料／药材】{"1":"干白芨","2":"药材","3":"晒干切片的白芨","4":"可研末配制止血药","5":"3"}。矿石、妖丹等材料填真实加工用途，不写成穿戴加成。',
      '【信物／杂物】{"1":"红绳木鱼","2":"重要物品","3":"韩小妹亲手雕刻的小木鱼，以红绳串系","4":"留念的亲情信物","5":"1"}；{"1":"旧竹筐","2":"杂物","3":"竹篾编成的旧筐","4":"用来背运采来的药材","5":"1"}。阵盘按实际布阵用途记录，只有证据表明是可装备的器物时才进相应槽。',
      '有实物才登记持有。NPC本人获得可学习功法即触发基础学习并将同一本经卷从背包移入对应 technique 槽，不等待额外一句“已学会”；已有主修冲突须按真实修习/改修情节处理，无改修依据保留原主修并说明冲突，不无脑覆盖。明确不能学习、条件不足或替人保管时留在背包并记录原因。功法资料不代表另有一份实物，搬槽不得重发或复制库存；学习不等于高阶修成或境界突破。',
      '逐 NPC 核对装备：从其已持有物中选当前真正能发挥作用的最优组合，先核对栏位、白值门槛、境界与剧情限制，再比较实际收益。功法槽以本人实际正在修习的功法为准，不以背包里另一本秘籍的名义品阶覆盖。收益相当或不能证明更优时保留原装备。换装只转移同一实例、退回被换下物，不复制、不改持有总数；已装备的物品才按本地规则计算加成。'
    ].join('\n')
  };
}

