function frAdaptBackgroundIntroductionRules(preset) {
  var meta = frPresetCompatMeta(preset);
  if (meta.backgroundIntroductionVersion === 1) return;
  var recognized = Object.create(null);
  var visited = Object.create(null);
  FR_BACKGROUND_RULE_PATCHES.forEach(function(patch) {
    var key = patch.scope + ':' + patch.id; if (visited[key]) return; visited[key] = true;
    var rules = patch.scope === 'entrySharedRules' ? (preset.entrySharedRules || []) : frPresetCompatRules(preset, patch.scope);
    var matches = rules.filter(function(rule) { return rule && rule.id === patch.id; });
    if (matches.length !== 1 || typeof matches[0].content !== 'string') {
      matches.forEach(function(rule) { frPresetCompatWarning(meta,patch.scope,rule,'background_ambiguous_rule_preserved'); }); return;
    }
    var rule = matches[0], text = rule.content;
    var variants = FR_BACKGROUND_RULE_PATCHES.filter(function(p) { return p.scope===patch.scope && p.id===patch.id; });
    for (var i=0; i<variants.length; i+=1) {
      var candidate=variants[i];
      if (text.length>=candidate.newLength && frCompatSha256Hex(text.slice(0,candidate.newLength))===candidate.newHash) { recognized[patch.scope]=true; return; }
      if (text.length>=candidate.length && frCompatSha256Hex(text.slice(0,candidate.length))===candidate.oldHash) {
        var body=text.slice(0,candidate.length);
        candidate.edits.forEach(function(edit) { body=body.split(edit[0]).join(edit[1]); });
        frPresetCompatBackup(meta,patch.scope,rule); rule.content=body+text.slice(candidate.length);
        recognized[patch.scope]=true; return;
      }
    }
    frPresetCompatWarning(meta,patch.scope,rule,'background_custom_rule_preserved');
  });
  // 已投影过的原生骨架也是可信锚点；不据 catalog id 或 marker 强改自定义。
  var merged = frPresetCompatRules(preset,'merged_variables');
  if (merged.some(function(rule) { return rule && rule.id === 'mv-4' && rule.content === frNativeEvolutionEntryContract(); })) recognized.merged_variables = true;
  FR_BACKGROUND_RULE_SPECS.forEach(function(spec) {
    var rules = spec.scope === 'entrySharedRules' ? preset.entrySharedRules : (preset.prompts && preset.prompts[spec.scope] && preset.prompts[spec.scope].rules);
    if (!Array.isArray(rules)) return;
    var matches = rules.filter(function(rule) { return rule && rule.id === spec.rule.id; });
    if (matches.length) {
      if (matches.length !== 1 || matches[0].content !== spec.rule.content) matches.forEach(function(rule) { frPresetCompatWarning(meta,spec.scope,rule,'background_custom_contract_preserved'); });
      return;
    }
    if (recognized[spec.scope]) rules.push(frPresetCompatCopy(spec.rule));
    else frPresetCompatWarning(meta,spec.scope,spec.rule,'background_unknown_scope_preserved');
  });
  meta.backgroundIntroductionVersion = 1;
}


