function frAdaptSourcePurposeRules(preset) {
  var meta=frPresetCompatMeta(preset),scopes=['sharedRules','itemSharedRules','entrySharedRules','merged_variables'];
  scopes.forEach(function(scope){
    var rules=scope.endsWith('Rules')?preset[scope]:(preset.prompts&&preset.prompts[scope]&&preset.prompts[scope].rules);if(!Array.isArray(rules))return;
    var existing=rules.filter(function(r){return r&&r.id===FR_SOURCE_PURPOSE_RULE.id;});
    if(existing.length){
      existing.forEach(function(r){var text=String(r.content||'');if(existing.length!==1||text.length<FR_SOURCE_PURPOSE_RULE.content.length||frCompatSha256Hex(text.slice(0,FR_SOURCE_PURPOSE_RULE.content.length))!==frCompatSha256Hex(FR_SOURCE_PURPOSE_RULE.content))frPresetCompatWarning(meta,scope,r,'source_purpose_custom_contract_preserved');});return;
    }
    var candidates=FR_SOURCE_PURPOSE_ANCHORS.filter(function(a){return a.scope===scope;}),anchorId=candidates[0]&&candidates[0].id,matches=rules.filter(function(r){return r&&r.id===anchorId;});
    if(matches.length!==1||typeof matches[0].content!=='string'){matches.forEach(function(r){frPresetCompatWarning(meta,scope,r,'source_purpose_ambiguous_anchor_preserved');});return;}
    var anchor=matches[0],text=anchor.content,known=candidates.some(function(a){return text.length>=a.length&&frCompatSha256Hex(text.slice(0,a.length))===a.hash;});
    if(!known){frPresetCompatWarning(meta,scope,anchor,'source_purpose_unknown_anchor_preserved');return;}
    var addition=frPresetCompatCopy(FR_SOURCE_PURPOSE_RULE);addition.enabled=anchor.enabled!==false;rules.push(addition);
  });
  meta.sourcePurposeVersion=1;
}

